#include <iostream>
using namespace std;

struct ChainNode {
    int data;
    ChainNode *next;
    ChainNode(int d) : data(d), next(0) {}
};

ChainNode* build(int n) {
    ChainNode *first = 0, *rear = 0;
    for (int i = 0; i < n; i++) {
        int v;
        cin >> v;
        ChainNode *s = new ChainNode(v);
        if (first == 0) first = rear = s;
        else { rear->next = s; rear = s; }
    }
    return first;
}

int main() {
    int n, m;
    if (!(cin >> n)) return 0;
    ChainNode *A = build(n);
    cin >> m;
    ChainNode *B = build(m);

    ChainNode *p = A, *q = B, *head = 0, *tail = 0;
    while (p != 0 && q != 0) {
        ChainNode *pick;
        if (p->data <= q->data) { pick = p; p = p->next; }
        else { pick = q; q = q->next; }
        if (head == 0) head = tail = pick;
        else { tail->next = pick; tail = pick; }
    }
    ChainNode *rest = (p != 0) ? p : q;    // 没走完的那一段
    if (head == 0) head = rest;
    else tail->next = rest;

    if (head == 0) {
        cout << "empty\n";
        return 0;
    }
    for (ChainNode *t = head; t != 0; t = t->next)
        cout << t->data << (t->next == 0 ? '\n' : ' ');
    return 0;
}
